create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
create table public.app_settings(id boolean primary key default true check(id),owner_id uuid unique references auth.users(id) on delete restrict,business_name text not null default 'Bella del Gelato Inventory',owner_email text,timezone text not null default 'Asia/Kolkata',report_day smallint not null default 1 check(report_day between 0 and 6),report_enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.app_settings(id) values(true) on conflict(id) do nothing;
create or replace function private.is_owner() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.app_settings s where s.id is true and s.owner_id=(select auth.uid())); $$;
revoke all on function private.is_owner() from public,anon;
grant execute on function private.is_owner() to authenticated;
create table public.ingredients(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),name text not null,category text not null default 'Other',unit text not null check(unit in ('g','kg','ml','L','pcs')),quantity numeric(14,3) not null default 0 check(quantity>=0),reorder_level numeric(14,3) not null default 0 check(reorder_level>=0),cost_per_unit numeric(14,4) check(cost_per_unit is null or cost_per_unit>=0),supplier text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,name));
create table public.ingredient_movements(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),ingredient_id bigint not null,movement_type text not null check(movement_type in ('opening','purchase','production','waste','adjustment','base_batch')),quantity_delta numeric(14,3) not null check(quantity_delta<>0),unit text not null,reason text,reference_id bigint,created_at timestamptz not null default now(),foreign key(owner_id,ingredient_id) references public.ingredients(owner_id,id) on delete cascade);
create index ingredient_movements_owner_date_idx on public.ingredient_movements(owner_id,created_at desc);
create table public.recipes(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),name text not null,category text not null default 'Milk gelato',yield_liters numeric(12,3) not null check(yield_liters>0),base_liters numeric(12,3) not null default 0 check(base_liters>=0),instructions text,archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,id),unique(owner_id,name));
create table public.recipe_ingredients(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),recipe_id bigint not null,ingredient_id bigint not null,quantity numeric(14,3) not null check(quantity>0),created_at timestamptz not null default now(),foreign key(owner_id,recipe_id) references public.recipes(owner_id,id) on delete cascade,foreign key(owner_id,ingredient_id) references public.ingredients(owner_id,id) on delete restrict,unique(owner_id,recipe_id,ingredient_id));
create table public.base_recipes(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),name text not null default 'Classic milk base',yield_liters numeric(12,3) not null check(yield_liters>0),instructions text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,id));
create table public.base_recipe_ingredients(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),base_recipe_id bigint not null,ingredient_id bigint not null,quantity numeric(14,3) not null check(quantity>0),foreign key(owner_id,base_recipe_id) references public.base_recipes(owner_id,id) on delete cascade,foreign key(owner_id,ingredient_id) references public.ingredients(owner_id,id) on delete restrict,unique(owner_id,base_recipe_id,ingredient_id));
create table public.base_batches(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),base_recipe_id bigint,name text not null,made_at timestamptz not null default now(),best_before date,quantity_liters numeric(12,3) not null check(quantity_liters>0),remaining_liters numeric(12,3) not null check(remaining_liters>=0 and remaining_liters<=quantity_liters),notes text,unique(owner_id,id),foreign key(owner_id,base_recipe_id) references public.base_recipes(owner_id,id) on delete restrict);
create index base_batches_fifo_idx on public.base_batches(owner_id,best_before,made_at) where remaining_liters>0;
create table public.base_batch_ingredients(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),base_batch_id bigint not null,ingredient_id bigint not null,quantity numeric(14,3) not null check(quantity>0),unit text not null,foreign key(owner_id,base_batch_id) references public.base_batches(owner_id,id) on delete cascade,foreign key(owner_id,ingredient_id) references public.ingredients(owner_id,id) on delete restrict);
create table public.production_batches(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),recipe_id bigint,recipe_name text not null,produced_at timestamptz not null default now(),yield_liters numeric(12,3) not null check(yield_liters>0),notes text,unique(owner_id,id),foreign key(owner_id,recipe_id) references public.recipes(owner_id,id) on delete restrict);
create index production_batches_owner_date_idx on public.production_batches(owner_id,produced_at desc);
create table public.production_batch_ingredients(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),production_batch_id bigint not null,ingredient_id bigint,ingredient_name text not null,quantity numeric(14,3) not null check(quantity>0),unit text not null,foreign key(owner_id,production_batch_id) references public.production_batches(owner_id,id) on delete cascade,foreign key(owner_id,ingredient_id) references public.ingredients(owner_id,id) on delete restrict);
create table public.base_batch_usages(id bigint generated always as identity primary key,owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(),production_batch_id bigint not null,base_batch_id bigint not null,quantity_liters numeric(12,3) not null check(quantity_liters>0),created_at timestamptz not null default now(),foreign key(owner_id,production_batch_id) references public.production_batches(owner_id,id) on delete cascade,foreign key(owner_id,base_batch_id) references public.base_batches(owner_id,id) on delete restrict);
alter table public.app_settings enable row level security;
create policy owner_can_read_settings on public.app_settings for select to authenticated using(private.is_owner());
create policy owner_can_update_settings on public.app_settings for update to authenticated using(private.is_owner()) with check(private.is_owner());
grant select on public.app_settings to authenticated;
grant update(business_name,owner_email,timezone,report_day,report_enabled) on public.app_settings to authenticated;
do $$ declare t text; begin foreach t in array array['ingredients','ingredient_movements','recipes','recipe_ingredients','base_recipes','base_recipe_ingredients','base_batches','base_batch_ingredients','production_batches','production_batch_ingredients','base_batch_usages'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy owner_access on public.%I for all to authenticated using(private.is_owner() and owner_id=(select auth.uid())) with check(private.is_owner() and owner_id=(select auth.uid()))',t); execute format('revoke all on public.%I from anon',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
revoke all on all tables in schema public from anon;
grant usage,select on all sequences in schema public to authenticated;
create or replace function private.record_stock_movement() returns trigger language plpgsql security definer set search_path='' as $$ declare d numeric; t text; why text; ref bigint; begin if tg_op='INSERT' then d:=new.quantity; t:='opening'; elsif new.quantity is distinct from old.quantity then d:=new.quantity-old.quantity; t:=coalesce(nullif(current_setting('app.stock_movement_type',true),''),'adjustment'); else return new; end if; why:=nullif(current_setting('app.stock_movement_reason',true),''); ref:=nullif(current_setting('app.stock_movement_reference',true),'')::bigint; if d<>0 then insert into public.ingredient_movements(owner_id,ingredient_id,movement_type,quantity_delta,unit,reason,reference_id) values(new.owner_id,new.id,t,d,new.unit,why,ref); end if; return new; end; $$;
revoke all on function private.record_stock_movement() from public,anon,authenticated;
create trigger ingredient_stock_ledger after insert or update of quantity on public.ingredients for each row execute function private.record_stock_movement();
create or replace function public.adjust_inventory(p_ingredient_id bigint,p_new_quantity numeric,p_reason text,p_movement_type text default 'adjustment') returns void language plpgsql security definer set search_path='' as $$ declare v_owner uuid:=auth.uid(); begin if v_owner is null or not private.is_owner() then raise exception 'Not authorized'; end if; if p_new_quantity<0 then raise exception 'Quantity cannot be negative'; end if; if p_movement_type not in ('purchase','waste','adjustment') then raise exception 'Invalid movement type'; end if; perform set_config('app.stock_movement_type',p_movement_type,true); perform set_config('app.stock_movement_reason',left(coalesce(p_reason,''),300),true); update public.ingredients set quantity=p_new_quantity where id=p_ingredient_id and owner_id=v_owner; if not found then raise exception 'Ingredient not found'; end if; end; $$;
create or replace function public.create_base_batch(p_name text,p_quantity_liters numeric,p_best_before date,p_items jsonb,p_base_recipe_id bigint default null) returns bigint language plpgsql security definer set search_path='' as $$ declare v_owner uuid:=auth.uid(); v_batch bigint; v_item jsonb; v_ingredient public.ingredients%rowtype; v_qty numeric; begin if v_owner is null or not private.is_owner() then raise exception 'Not authorized'; end if; if p_quantity_liters<=0 or jsonb_typeof(p_items)<>'array' then raise exception 'Invalid batch details'; end if; insert into public.base_batches(owner_id,base_recipe_id,name,best_before,quantity_liters,remaining_liters) values(v_owner,p_base_recipe_id,left(p_name,120),p_best_before,p_quantity_liters,p_quantity_liters) returning id into v_batch; for v_item in select value from jsonb_array_elements(p_items) loop v_qty:=(v_item->>'quantity')::numeric; select * into v_ingredient from public.ingredients where id=(v_item->>'ingredient_id')::bigint and owner_id=v_owner for update; if not found or v_qty<=0 then raise exception 'Invalid base recipe ingredient'; end if; if v_ingredient.quantity<v_qty then raise exception 'Not enough % in stock',v_ingredient.name; end if; insert into public.base_batch_ingredients(owner_id,base_batch_id,ingredient_id,quantity,unit) values(v_owner,v_batch,v_ingredient.id,v_qty,v_ingredient.unit); perform set_config('app.stock_movement_type','base_batch',true); perform set_config('app.stock_movement_reason','Used to make '||left(p_name,120),true); perform set_config('app.stock_movement_reference',v_batch::text,true); update public.ingredients set quantity=quantity-v_qty where id=v_ingredient.id and owner_id=v_owner; end loop; return v_batch; end; $$;
create or replace function public.log_production(p_recipe_id bigint,p_yield_liters numeric,p_produced_at timestamptz default now(),p_notes text default null) returns bigint language plpgsql security definer set search_path='' as $$ declare v_owner uuid:=auth.uid(); v_recipe public.recipes%rowtype; v_recipe_item record; v_ingredient public.ingredients%rowtype; v_batch_id bigint; v_need numeric; v_use numeric; v_base record; begin if v_owner is null or not private.is_owner() then raise exception 'Not authorized'; end if; if p_yield_liters<=0 then raise exception 'Batch size must be positive'; end if; select * into v_recipe from public.recipes where id=p_recipe_id and owner_id=v_owner and not archived for share; if not found then raise exception 'Recipe not found'; end if; insert into public.production_batches(owner_id,recipe_id,recipe_name,produced_at,yield_liters,notes) values(v_owner,v_recipe.id,v_recipe.name,p_produced_at,p_yield_liters,left(p_notes,1000)) returning id into v_batch_id; for v_recipe_item in select ri.ingredient_id,ri.quantity,i.name,i.unit from public.recipe_ingredients ri join public.ingredients i on i.id=ri.ingredient_id and i.owner_id=ri.owner_id where ri.owner_id=v_owner and ri.recipe_id=v_recipe.id loop v_need:=v_recipe_item.quantity*p_yield_liters/v_recipe.yield_liters; select * into v_ingredient from public.ingredients where id=v_recipe_item.ingredient_id and owner_id=v_owner for update; if v_ingredient.quantity<v_need then raise exception 'Not enough % in stock',v_ingredient.name; end if; insert into public.production_batch_ingredients(owner_id,production_batch_id,ingredient_id,ingredient_name,quantity,unit) values(v_owner,v_batch_id,v_ingredient.id,v_ingredient.name,v_need,v_ingredient.unit); perform set_config('app.stock_movement_type','production',true); perform set_config('app.stock_movement_reason','Used for '||v_recipe.name,true); perform set_config('app.stock_movement_reference',v_batch_id::text,true); update public.ingredients set quantity=quantity-v_need where id=v_ingredient.id and owner_id=v_owner; end loop; v_need:=v_recipe.base_liters*p_yield_liters/v_recipe.yield_liters; if v_need>0 then for v_base in select id,remaining_liters from public.base_batches where owner_id=v_owner and remaining_liters>0 order by best_before nulls last,made_at,id for update loop exit when v_need<=0; v_use:=least(v_need,v_base.remaining_liters); update public.base_batches set remaining_liters=remaining_liters-v_use where id=v_base.id and owner_id=v_owner; insert into public.base_batch_usages(owner_id,production_batch_id,base_batch_id,quantity_liters) values(v_owner,v_batch_id,v_base.id,v_use); v_need:=v_need-v_use; end loop; if v_need>0 then raise exception 'Not enough milk base in stock'; end if; insert into public.production_batch_ingredients(owner_id,production_batch_id,ingredient_id,ingredient_name,quantity,unit) values(v_owner,v_batch_id,null,'Milk base',v_recipe.base_liters*p_yield_liters/v_recipe.yield_liters,'L'); end if; return v_batch_id; end; $$;
revoke all on function public.adjust_inventory(bigint,numeric,text,text) from public,anon;
revoke all on function public.create_base_batch(text,numeric,date,jsonb,bigint) from public,anon;
revoke all on function public.log_production(bigint,numeric,timestamptz,text) from public,anon;
grant execute on function public.adjust_inventory(bigint,numeric,text,text) to authenticated;
grant execute on function public.create_base_batch(text,numeric,date,jsonb,bigint) to authenticated;
grant execute on function public.log_production(bigint,numeric,timestamptz,text) to authenticated;
revoke insert,update,delete on public.ingredient_movements,public.base_batch_ingredients,public.base_batches,public.production_batches,public.production_batch_ingredients,public.base_batch_usages from authenticated;
